doc.sourceCode:
/* ==UserStyle==
@name           All Emirates Sites
@namespace      github.com/seenukarthi/Stylus
@version        1.0.0
@description    This Style Sheet for most of the Emirates website.
@author         Karthikeyan Vaithilingam
==/UserStyle== */
@-moz-document domain("emirates.com"),
domain("emirates.group") {
    *:not(pre, pre code, code, .ms-Icon, .icon-*) {
        font-family: var(--vknDefaultFontFamily) !important;
        font-weight: 500;
    }

    pre,
    pre code,
    code {
        font-family: var(--vknMonoFontFamily) !important;
        font-size: inherit;
    }
}

@-moz-document domain("confluence.emirates.com") {
    #header-precursor {
        display: none;
    }
    #likes-section,
    .labels-content {
        font-weight: inherit;
    }

    html {
        font-family: var(--vknDefaultFontFamily) !important;
    }
    p,li,span {
        font-weight: 500;
    }

}

@-moz-document domain("jiraagile.emirates.com") {
    #announcement-banner {
        display: none;
    }

    html {
        font-family: var(--vknDefaultFontFamily) !important;
    }
}

@-moz-document domain("waqti.emirates.group") {
    button,
    input,
    optgroup,
    select,
    textarea {
        font-size: 14px;
    }
}

@-moz-document domain("emiratesgroup.sharepoint.com") {
    .ms-DetailsRow-cell {
        font-family: var(--vknMonoFontFamily) !important;
        font-size: 12px;
    }
}

@-moz-document domain("emiratesgroup.service-now.com") {
    *:not(pre, pre code, code, .glyphicon) {
        font-family: var(--vknDefaultFontFamily) !important;
    }

    body {
        --now-global-font-size--md: 12px;
    }

    pre,
    pre code,
    code {
        font-family: var(--vknMonoFontFamily) !important;
        font-size: inherit;
    }

    .table > thead > tr > th,
    .table > thead > tr > td,
    .table > tbody > tr > th,
    .table > tbody > tr > td,
    .table > tfoot > tr > th,
    .table > tfoot > tr > td {
        font-size: 12px;
    }

    .form-control {
        font-size: 12px;
    }

    .label-text {
        font-weight: inherit;
    }

    body {
        font-size: 12px;
    }

    .btn-icon {
        font-size: 20px;
    }

    .grid-widget-header {
        font-size: inherit;
    }

    .-polaris {
        --now-checkbox--opacity--disabled: 0.5;
    }

    .vt {
        white-space: nowrap;
    }
}

@-moz-document url-prefix("https://emiratesgroup.service-now.com/tech_debt_summary") {
    body {
        zoom: 80%
    }
}
